import pathlib, re, sys, subprocess
root = pathlib.Path(sys.argv[1])
wiki = root / 'wiki'
pages = sorted(wiki.rglob('*.md'))
bad = []
linked_from_index = set()
for p in pages:
    txt = p.read_text(encoding='utf-8')
    if not txt.startswith('---\n'):
        bad.append(('sin yaml', p))
    for k in ['tipo:', 'fuentes:', 'fecha_datos:', 'estado:', 'actualizado:']:
        if k not in txt.split('---')[1]:
            bad.append(('falta ' + k, p))
    for m in re.finditer(r'\]\(([^)\s]+)\)', txt):
        href = m.group(1)
        if href.startswith('http'):
            continue
        path = href.split('#')[0].replace('%20', ' ')
        if not path:
            continue
        tgt = (p.parent / path).resolve()
        if not tgt.exists():
            bad.append(('roto', p.relative_to(root), href))
        if p.name == 'index.md' and p.parent == wiki:
            linked_from_index.add(tgt)
for p in pages:
    if p.name != 'index.md' and p.resolve() not in linked_from_index:
        bad.append(('no enlazada desde index', p.relative_to(root)))
print(len(pages), 'paginas')
for b in bad:
    print(b)
# run recalc commands
for p in pages:
    for line in p.read_text(encoding='utf-8').splitlines():
        if line.startswith('    python3 -c '):
            cmd = line.strip()
            r = subprocess.run(cmd, shell=True, cwd=root, capture_output=True, text=True)
            print('==', p.name, '->', r.returncode, r.stdout.strip()[:400], r.stderr.strip()[:300])

